462	void FPGA::SetupDFT(uint32_t f_firstBin, uint32_t f_binSpacing) {
463		// see FPGA protocol for formulas
464		uint16_t firstBin = f_firstBin * (1ULL << 16) / ADC_samplerate;
465		uint16_t binSpacing = f_binSpacing * (1ULL << 24) / ADC_samplerate;
466		WriteRegister(Reg::DFTFirstBin, firstBin);
467		WriteRegister(Reg::DFTFreqSpacing, binSpacing);
468	}
